        static Raw13CaptureHeader Header(string sequence="1074")=>new Raw13CaptureHeader{name="Generated coherent fixture",countryCode="GB",timeZone="Europe/London",datasetVersion="fixture/"+sequence,datasetSource="https://example.invalid/unverified-selection",latitude=51.671156,longitude=-3.131748,size=3000,gridSide=2,drivingSide=-1};
