        static GeoBuilding[] Buildings()=>new[]{new GeoBuilding{id="regional-fixture",kind="yes",roof="flat",height=6,measuredHeight=false,points=new[]{new Vector3(-2000,10,-2000),new Vector3(2000,10,-2000),new Vector3(2000,10,2000),new Vector3(-2000,10,2000),new Vector3(-2000,10,-2000)}}};
        static CoherentSqliteCaptureRequest Request(string db,string grid,string sequence="1074",CoherentSqliteBudgets budgets=null)
        {byte[] bytes=File.ReadAllBytes(grid);return new CoherentSqliteCaptureRequest(db,Header(sequence),Pins(sequence),new CaptureFilePin(grid,bytes.Length,World13DocumentCodec.Hash(bytes)),null,Buildings(),Encoding.UTF8.GetBytes("generated regional policy; UNVERIFIED"),budgets);}
        public static Report Execute(string output)
