            if(Directory.Exists(output)||!Path.GetFullPath(output).StartsWith("/private/tmp/rr019-sqlite-proof-",StringComparison.Ordinal))throw new InvalidOperationException("Fresh fixture-owned source root required");Directory.CreateDirectory(output);var r=new Report();
            try
