                string database=Path.Combine(output,"fixture source ?#.sqlite"),grid=Path.Combine(output,"grid.f32");byte[] originalGrid=new byte[16];for(int i=0;i<4;i++)Buffer.BlockCopy(BitConverter.GetBytes(100f),0,originalGrid,i*4,4);File.WriteAllBytes(grid,originalGrid);
                using(var writer=new CoherentSqliteFixture(database))
