                    writer.Create();writer.Add(1,0,new[]{-2000.0,2000.0},new[]{0.0,0.0});for(int i=2;i<=8;i++)writer.Add(i,0,new[]{-800.0+i*80,-760.0+i*80},new[]{100.0,100.0});writer.Add(99,2,new[]{-2000.0,2000.0,2000.0,-2000.0,-2000.0},new[]{-2000.0,-2000.0,2000.0,2000.0,-2000.0});writer.Add(1,4,new[]{-2000.0,2000.0},new[]{0.0,0.0},true);writer.Add(100,0,new[]{4000.0,4100.0},new[]{0.0,0.0});
