                        {Check(r,q.Step(),"SQL storage-class adversarial row exists");foreach(int column in new[]{0,1,2})Reject(r,()=>q.Integer(column),"non-INTEGER column rejected without SQLite coercion "+column);Check(r,q.Integer(3)==7,"genuine INTEGER preserved");Reject(r,()=>q.Text(3,8),"INTEGER is not silently coerced to TEXT");Reject(r,()=>q.Blob(0,8),"NULL is not silently accepted as empty BLOB");}
                    }
                    using(var cancelCleanup=new CancellationTokenSource())
