                    var request=Request(database,grid);var first=CoherentRaw13SqliteCapture.Capture(request,CancellationToken.None);r.baselineRowsSha=first.Receipt.selectedRowsSha256;
                    Check(r,!first.SourceAuthority&&first.Receipt.mainDatabaseReadOnly&&first.Receipt.totalChanges==0&&first.Receipt.queryOnly==1,"coherent result is copied/unverified with explicit noDML diagnostics");
                    Check(r,first.Receipt.selectedRows==10&&first.Receipt.uniqueWays==9&&first.Receipt.rawReferences==23&&first.Receipt.uniqueWayReferences==21,"whole selected rows/ordered refs and dual-use merge counts exact");
                    Check(r,first.Receipt.zeroInWindowNodeRows==3,"crossing road/rail plus enclosing polygon retained despite zero in-box nodes");
                    using(var reader=new ReadOnlyCaptureSqlite(database,CancellationToken.None))using(var q=reader.Select("SELECT (SELECT count(*) FROM features)+(SELECT count(*) FROM railways)")){Check(r,q.Step()&&q.Integer(0)==11&&first.Receipt.selectedRows==10,"supported RTree capture excludes the one completely outside fixture way");}
                    Check(r,first.Receipt.highways==8&&first.Receipt.baselineBuildings==1&&first.Receipt.railways==1,"complete supported-way classes retained, no node seed or LIMIT");
                    var converted=OriginalWayRaw13Converter.ConvertUnverifiedForInspection(first.PayloadForInspection,"RoadRush/0.19.0/geometry13",CancellationToken.None);Check(r,!converted.Report.reviewedFrozenCapture&&!converted.CommitCapability&&converted.Report.outputRoadEdges==8,"actual typed payload converts but cannot mint source/commit authority");
                    var repeat=CoherentRaw13SqliteCapture.Capture(request,CancellationToken.None);Check(r,repeat.Receipt.selectedRowsSha256==first.Receipt.selectedRowsSha256&&repeat.PayloadForInspection.InputDigest==first.PayloadForInspection.InputDigest,"same source snapshot/grid read is deterministic");
                    bool committed=false;var oldSnapshot=CoherentRaw13SqliteCapture.Capture(request,CancellationToken.None,null,p=>{if(p==CoherentRaw13SqliteCapture.Phase.SnapshotMetadata&&!committed){writer.Exec("BEGIN IMMEDIATE");writer.Run("UPDATE features SET tags=?1 WHERE id=1","{\"highway\":\"residential\",\"name\":\"NEW\"}");writer.Run("UPDATE railways SET tags=?1 WHERE id=1","{\"highway\":\"residential\",\"railway\":\"tram\",\"name\":\"NEW\"}");writer.Run("UPDATE metadata SET value=?1 WHERE key='osmosis_replication_sequence_number'","1075");writer.Exec("COMMIT");committed=true;}});
                    r.walSnapshotRowsSha=oldSnapshot.Receipt.selectedRowsSha256;Check(r,committed&&oldSnapshot.Receipt.selectedRowsSha256==first.Receipt.selectedRowsSha256&&oldSnapshot.Receipt.metadata.Contains("osmosis_replication_sequence_number=1074"),"live WAL writer commits while reader retains coherent1074 metadata AND old rows");
                    Reject(r,()=>CoherentRaw13SqliteCapture.Capture(request,CancellationToken.None),"fresh reader rejects stale externally selected1074 after committed1075");var next=CoherentRaw13SqliteCapture.Capture(Request(database,grid,"1075"),CancellationToken.None);r.newSnapshotRowsSha=next.Receipt.selectedRowsSha256;Check(r,next.Receipt.selectedRowsSha256!=first.Receipt.selectedRowsSha256&&next.Receipt.metadata.Contains("osmosis_replication_sequence_number=1075"),"fresh1075 selection captures new metadata AND new rows");
                    request=Request(database,grid,"1075");foreach(CoherentRaw13SqliteCapture.Phase phase in Enum.GetValues(typeof(CoherentRaw13SqliteCapture.Phase)))using(var cancel=new CancellationTokenSource())Reject(r,()=>CoherentRaw13SqliteCapture.Capture(request,cancel.Token,null,p=>{if(p==phase)cancel.Cancel();}),"cancel disposes snapshot/returns no partial at "+phase);
                    bool current=true;Reject(r,()=>CoherentRaw13SqliteCapture.Capture(request,CancellationToken.None,()=>current,p=>{if(p==CoherentRaw13SqliteCapture.Phase.RowsCopied)current=false;}),"stale generation returns no capture");
                    foreach(var budget in new[]{new CoherentSqliteBudgets(rows:1),new CoherentSqliteBudgets(references:1),new CoherentSqliteBudgets(encodedBytes:1)})Reject(r,()=>CoherentRaw13SqliteCapture.Capture(Request(database,grid,"1075",budget),CancellationToken.None),"whole request budget refusal, never row/ref/byte thinning");
                    request=Request(database,grid,"1075");try{Reject(r,()=>CoherentRaw13SqliteCapture.Capture(request,CancellationToken.None,null,p=>{if(p==CoherentRaw13SqliteCapture.Phase.GridRead){var changed=(byte[])originalGrid.Clone();changed[0]^=1;File.WriteAllBytes(grid,changed);}}),"grid mutation after initial read fails pinned final check while DB snapshot held");}finally{File.WriteAllBytes(grid,originalGrid);}
                    var restored=CoherentRaw13SqliteCapture.Capture(Request(database,grid,"1075"),CancellationToken.None);Check(r,restored.Receipt.gridSha256==World13DocumentCodec.Hash(originalGrid)&&restored.Receipt.totalChanges==0,"cancel/budget/grid failures release locks; retry succeeds");
                    writer.Exec("BEGIN IMMEDIATE");writer.Run("UPDATE metadata SET value=?1 WHERE key='osmosis_replication_sequence_number'","9999");var uncommitted=CoherentRaw13SqliteCapture.Capture(Request(database,grid,"1075"),CancellationToken.None);Check(r,uncommitted.Receipt.metadata.Contains("osmosis_replication_sequence_number=1075"),"reader never observes uncommitted writer metadata");writer.Exec("ROLLBACK");
                    byte[] originalGeometry;using(var reader=new ReadOnlyCaptureSqlite(database,CancellationToken.None))using(var q=reader.Select("SELECT geometry FROM features WHERE id=2")){Check(r,q.Step(),"malformed-row fixture source exists");originalGeometry=q.Blob(0,800004);}try{writer.Run("UPDATE features SET geometry=?1 WHERE id=2",new byte[]{2,0,0,0});Reject(r,()=>CoherentRaw13SqliteCapture.Capture(Request(database,grid,"1075"),CancellationToken.None),"malformed geometry count/length rejected in preflight before full BLOB fetch");}finally{writer.Run("UPDATE features SET geometry=?1 WHERE id=2",originalGeometry);}
                    using(var cancel=new CancellationTokenSource())using(var reader=new ReadOnlyCaptureSqlite(database,cancel.Token,5))
                    {var elapsed=System.Diagnostics.Stopwatch.StartNew();var cancellation=Task.Run(()=>{Thread.Sleep(20);cancel.Cancel();});Reject(r,()=>{using(var q=reader.Select("WITH RECURSIVE c(x) AS (VALUES(0) UNION ALL SELECT x+1 FROM c WHERE x<100000000) SELECT sum(x) FROM c"))q.Step();},"native SQLite progress callback interrupts long read on worker cancellation");cancellation.Wait();Check(r,elapsed.Elapsed.TotalSeconds<2,"native progress cancellation exits within bounded2s safety window");}
                    using(var reader=new ReadOnlyCaptureSqlite(database,CancellationToken.None,.03)){var elapsed=System.Diagnostics.Stopwatch.StartNew();Reject(r,()=>{using(var q=reader.Select("WITH RECURSIVE c(x) AS (VALUES(0) UNION ALL SELECT x+1 FROM c WHERE x<100000000) SELECT sum(x) FROM c"))q.Step();},"native SQLite read deadline is bounded");Check(r,elapsed.Elapsed.TotalSeconds<2,"native VM deadline interrupts before the full long query completes");}
