    public static class CoherentSqliteCaptureVerification
    {
        public static void Run(){int exit=1;string output="/private/tmp/rr019-sqlite-proof-unity-"+DateTime.UtcNow.Ticks;try{if(Application.isPlaying||UnityEngine.Object.FindAnyObjectByType<GameSession>())throw new InvalidOperationException("Generated SQLite source proof only");var r=CoherentSqliteCaptureChecks.Execute(output);Debug.Log("COHERENT SQLITE PASS "+r.checks+" "+output);exit=0;}catch(Exception e){Debug.LogException(e);}EditorApplication.Exit(exit);}
    }
